--// Embedded icons ---------------------------------------------------------
local ICON_DATA = {
    close = "",
    check = "",
    chevron = "",
    home = "",
    settings = "",
    user = "",
    bolt = "",
    eye = "",
    sword = "",
    leaf = "",
    target = "",
    info = "",
    gamepad = "",
    copy = "",
    crown = "",
    shield = "",
    pin = "",
    sliders = "",
    globe = "",
