local FALLBACK_GLYPH = {
    close = "x", check = "+", chevron = "v", home = "H",
    settings = "S", user = "U", bolt = "!", eye = "O",
}

local ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local LOOKUP = {}
for i = 1, #ALPHABET do LOOKUP[ALPHABET:byte(i)] = i - 1 end

local function b64decode(s)
    s = (s:gsub("[^%w%+/]", ""))
    local out = {}
    for i = 1, #s, 4 do
        local chunk = s:sub(i, i + 3)
        local len = #chunk
        if len >= 2 then
            local a, b, c, d = chunk:byte(1, 4)
            local v = LOOKUP[a] * 262144 + LOOKUP[b] * 4096
                + (c and LOOKUP[c] or 0) * 64 + (d and LOOKUP[d] or 0)
            local b1 = math.floor(v / 65536) % 256
            local b2 = math.floor(v / 256) % 256
            local b3 = v % 256
            if len == 4 then
                out[#out + 1] = string.char(b1, b2, b3)
            elseif len == 3 then
                out[#out + 1] = string.char(b1, b2)
            else
                out[#out + 1] = string.char(b1)
            end
        end
    end
    return table.concat(out)
end

local iconCache = {}
local function getIcon(name)
    if iconCache[name] ~= nil then return iconCache[name] or nil end
    local id = false
    if type(name) == "number" or (type(name) == "string" and name:match("^%d+$")) then
        id = "rbxassetid://" .. tostring(name)
    elseif type(name) == "string" and name:find("rbxasset") then
        id = name
    elseif ICON_DATA[name] then
        pcall(function()
            local gca = getcustomasset or get_custom_asset or getsynasset
            if not (writefile and gca) then return end
            if makefolder and isfolder and not isfolder("Lumen") then makefolder("Lumen") end
            local path = "Lumen/" .. name .. ".png"
            writefile(path, b64decode(ICON_DATA[name]))
            id = gca(path)
        end)
    end
    iconCache[name] = id
    return id or nil
end

--// Theme / helpers ----------------------------------------------------------
local Theme = {
    Bg      = Color3.fromRGB(10, 10, 12),
    Panel   = Color3.fromRGB(16, 16, 19),
    Element = Color3.fromRGB(24, 24, 29),
    Hover   = Color3.fromRGB(38, 38, 45),
    Stroke  = Color3.fromRGB(52, 52, 60),
    Text    = Color3.fromRGB(240, 240, 245),
    Sub     = Color3.fromRGB(130, 130, 142),
    Accent  = Color3.fromRGB(255, 255, 255),
}

local NOTIFY_TINT = {
    warning = Color3.fromRGB(255, 200, 90),
    error   = Color3.fromRGB(255, 95, 95),
}
local NOTIFY_ICON = { info = "bolt", success = "check", warning = "bolt", error = "close" }

local function new(class, props, children)
    local o = Instance.new(class)
    local parent
    for k, v in pairs(props or {}) do
        if k == "Parent" then parent = v else o[k] = v end
    end
    for _, c in ipairs(children or {}) do c.Parent = o end
    if parent then o.Parent = parent end
    return o
end

local function corner(r)
    return new("UICorner", { CornerRadius = UDim.new(0, r) })
end

local function circle()
    return new("UICorner", { CornerRadius = UDim.new(1, 0) })
end

local function stroke(color, thickness, transparency)
    return new("UIStroke", {
        Color = color or Theme.Stroke,
        Thickness = thickness or 1,
        Transparency = transparency or 0,
        ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
    })
end

local function pad(l, t, r, b)
    return new("UIPadding", {
        PaddingLeft = UDim.new(0, l), PaddingTop = UDim.new(0, t),
        PaddingRight = UDim.new(0, r), PaddingBottom = UDim.new(0, b),
    })
end

local function tw(o, props, t, style, dir)
    local tween = TweenService:Create(o, TweenInfo.new(t or 0.3, style or ES.Quint, dir or ED.Out), props)
    tween:Play()
    return tween
end

local function label(p)
    local d = {
        BackgroundTransparency = 1, BorderSizePixel = 0,
        Font = Enum.Font.GothamMedium, TextSize = 13,
        TextColor3 = Theme.Text, TextXAlignment = Enum.TextXAlignment.Left,
    }
    for k, v in pairs(p) do d[k] = v end
    return new("TextLabel", d)
end

local function textWidth(text, size, font)
    return TextService:GetTextSize(text, size, font or Enum.Font.GothamMedium, Vector2.new(1000, 1000)).X
end

local function safe(cb, ...)
    if type(cb) ~= "function" then return end
    local ok, err = pcall(cb, ...)
    if not ok then warn("[Lumen] callback error: " .. tostring(err)) end
end

local function makeIcon(parent, name, size, color)
    local id = getIcon(name)
    local o
    if id then
        o = new("ImageLabel", {
            BackgroundTransparency = 1, Image = id, ImageColor3 = color,
            Size = UDim2.fromOffset(size, size),
            AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5),
        })
    else
        o = new("TextLabel", {
            BackgroundTransparency = 1, Font = Enum.Font.GothamBold, TextSize = size,
            Text = FALLBACK_GLYPH[name] or tostring(name):sub(1, 1):upper(),
            TextColor3 = color, Size = UDim2.fromScale(1, 1),
        })
    end
    o.Parent = parent
    return o
end

local function iconColor(o, c, t)
    tw(o, o:IsA("ImageLabel") and { ImageColor3 = c } or { TextColor3 = c }, t or 0.25)
end

local function setIconColor(o, c)
    if o:IsA("ImageLabel") then o.ImageColor3 = c else o.TextColor3 = c end
end

local function getGuiParent()
    local ok, r = pcall(function() return gethui and gethui() end)
    if ok and r then return r end
    local okCore = pcall(function()
        local t = Instance.new("Folder")
        t.Parent = CoreGui
        t:Destroy()
    end)
    if okCore then return CoreGui end
    return Players.LocalPlayer:WaitForChild("PlayerGui")
end

-- types text out letter by letter (MaxVisibleGraphemes); leaves the text visible on failure
local function typewrite(lbl, cps)
    local n = utf8.len(lbl.Text) or #lbl.Text
    if not pcall(function() lbl.MaxVisibleGraphemes = 0 end) then return end
    for i = 1, n do
        if not lbl.Parent then return end
        lbl.MaxVisibleGraphemes = i
        task.wait(1 / cps)
    end
    if lbl.Parent then lbl.MaxVisibleGraphemes = -1 end
end

--// Flags: read / write any element that was created with a Flag ---------------
function Lumen:GetFlag(flag)
    local o = Lumen.Flags[flag]
    if not o then return nil end
    if o.Type == "Dropdown" then return o.CurrentOption
    elseif o.Type == "Keybind" then return o.CurrentKeybind
    elseif o.Type == "ColorPicker" then return o.Color end
    return o.CurrentValue
end

function Lumen:SetFlag(flag, value, silent)
    local o = Lumen.Flags[flag]
    if not o then return false end
    o:Set(value, silent)
    return true
end

--// Window --------------------------------------------------------------------
function Lumen:CreateWindow(opts)
    opts = opts or {}
    Theme.Accent = opts.Accent or Color3.fromRGB(255, 255, 255)
    local titleText = opts.Title or opts.Name or "Lumen"
    local toggleKey = opts.ToggleKey or Enum.KeyCode.RightShift
    local size = opts.Size or UDim2.fromOffset(580, 390)
    do -- keep the window inside small screens (phones)
        local cam = workspace.CurrentCamera
        local vp = cam and cam.ViewportSize or Vector2.new(1920, 1080)
        size = UDim2.fromOffset(math.min(size.X.Offset, vp.X - 24), math.min(size.Y.Offset, vp.Y - 70))
    end
    local expandTabs = opts.TabStyle == "Expand" -- icon-only tabs, the active one shows its name
    local userScale = opts.Scale or 1

    local parent = getGuiParent()
    local old = parent:FindFirstChild("LumenUI")
    if old then old:Destroy() end

    local gui = new("ScreenGui", {
        Name = "LumenUI", ResetOnSpawn = false, IgnoreGuiInset = true,
        ZIndexBehavior = Enum.ZIndexBehavior.Sibling, DisplayOrder = 999,
    })
    pcall(function() if syn and syn.protect_gui then syn.protect_gui(gui) end end)
    gui.Parent = parent

    local conns = {}
    local function connect(sig, fn)
        local c = sig:Connect(fn)
        conns[#conns + 1] = c
        return c
    end

    local accentHooks = {}
    local function onAccent(fn)
        accentHooks[#accentHooks + 1] = fn
        fn()
    end

    local useIntro = opts.Intro ~= false
    local ready = not useIntro
    local destroying = false
    local visible = not useIntro
    local busy = false
    local setVisible -- assigned below

    --// Configuration saving (Rayfield style) ---------------------------------
    Lumen.Flags = {}
    local cfg = opts.ConfigurationSaving or {}
    local cfgEnabled = cfg.Enabled == true
    local cfgFolder = cfg.FolderName or "Lumen"
    local cfgPath = cfgFolder .. "/" .. tostring(cfg.FileName or game.PlaceId) .. ".json"

    local function saveConfig()
        if not cfgEnabled or not writefile then return end
        pcall(function()
            if makefolder and isfolder and not isfolder(cfgFolder) then makefolder(cfgFolder) end
            local data = {}
            for flag, o in pairs(Lumen.Flags) do
                if o.Type == "Toggle" or o.Type == "Slider" or o.Type == "Input" then
                    data[flag] = o.CurrentValue
                elseif o.Type == "Dropdown" then
                    data[flag] = o.CurrentOption
                elseif o.Type == "Keybind" then
                    data[flag] = o.CurrentKeybind
                elseif o.Type == "ColorPicker" then
                    local c = o.Color
                    data[flag] = {
                        R = math.floor(c.R * 255 + 0.5), G = math.floor(c.G * 255 + 0.5),
                        B = math.floor(c.B * 255 + 0.5),
                    }
                end
            end
            writefile(cfgPath, HttpService:JSONEncode(data))
        end)
    end

    function Lumen:LoadConfiguration()
        if not cfgEnabled or not (isfile and readfile) then return end
        pcall(function()
            if not isfile(cfgPath) then return end
            local data = HttpService:JSONDecode(readfile(cfgPath))
            for flag, value in pairs(data) do
                local o = Lumen.Flags[flag]
                if o then
                    task.spawn(function()
                        if o.Type == "ColorPicker" and type(value) == "table" then
                            o:Set(Color3.fromRGB(value.R, value.G, value.B))
                        else
                            o:Set(value)
                        end
                    end)
                end
            end
        end)
    end

    --// Main window (CanvasGroup => the whole window fades as one) -------------
    local main = new("CanvasGroup", {
        Name = "Main", Size = size, AnchorPoint = Vector2.new(0.5, 0.5),
        Position = UDim2.fromScale(0.5, 0.5),
        BackgroundColor3 = Theme.Bg, BackgroundTransparency = opts.Transparency or 0.1,
        BorderSizePixel = 0, GroupTransparency = useIntro and 1 or 0,
        Visible = not useIntro, Parent = gui,
    }, { corner(14), new("UIScale", { Scale = userScale }) })
    local scale = main:FindFirstChildOfClass("UIScale")

    -- soft top glow
    new("Frame", {
        Size = UDim2.new(1, 0, 0, 160), BackgroundColor3 = Color3.new(1, 1, 1),
        BorderSizePixel = 0, Parent = main,
    }, { new("UIGradient", { Rotation = 90, Transparency = NumberSequence.new(0.94, 1) }) })

    -- fixed-size layer: the window unfolds over it without squashing the layout
    local body = new("Frame", {
        Name = "Body", Size = UDim2.fromOffset(size.X.Offset, size.Y.Offset),
        AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5),
        BackgroundTransparency = 1, BorderSizePixel = 0, Parent = main,
    })
    -- border with a slowly rotating gradient (drawn as an inset overlay)
    local borderStroke = stroke(Color3.new(1, 1, 1), 1, 0)
    local borderGrad = new("UIGradient", {
        Rotation = 45,
        Color = ColorSequence.new(Color3.new(1, 1, 1), Color3.fromRGB(120, 120, 130)),
        Transparency = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 0.3),
            NumberSequenceKeypoint.new(0.5, 0.88),
            NumberSequenceKeypoint.new(1, 0.3),
        }),
    })
    borderGrad.Parent = borderStroke
    new("Frame", {
        Size = UDim2.new(1, -2, 1, -2), Position = UDim2.fromOffset(1, 1),
        BackgroundTransparency = 1, BorderSizePixel = 0, ZIndex = 50, Parent = main,
    }, { corner(13), borderStroke })
    connect(RunService.RenderStepped, function()
        if main.Visible then borderGrad.Rotation = (os.clock() * 25) % 360 end
    end)

    --// Blur behind the window only: a glass part right in front of the camera
    --// exactly over the window + DepthOfField near-blur (same trick as Rayfield)
    local blurEnabled = opts.Blur ~= false
    local blurOn = false
    for _, v in ipairs(Lighting:GetChildren()) do
        if v.Name == "LumenDoF" then v:Destroy() end
    end
    pcall(function() RunService:UnbindFromRenderStep("LumenGlass") end)
    local cam0 = workspace.CurrentCamera
    if cam0 then
        for _, v in ipairs(cam0:GetChildren()) do
            if v.Name == "LumenGlass" then v:Destroy() end
        end
    end
    local dof = new("DepthOfFieldEffect", {
        Name = "LumenDoF", Enabled = true, FarIntensity = 0, FocusDistance = 51.6,
        InFocusRadius = 50, NearIntensity = 0, Parent = Lighting,
    })
    local glass = new("Part", {
        Name = "LumenGlass", Anchored = true, CanCollide = false, CanQuery = false,
        CanTouch = false, CastShadow = false, Locked = true, Material = Enum.Material.Glass,
        BrickColor = BrickColor.new("Institutional white"), Transparency = 0.98,
        Size = Vector3.new(1, 1, 0.001),
    })
    RunService:BindToRenderStep("LumenGlass", Enum.RenderPriority.Last.Value, function()
        if not blurOn or not main.Visible then return end
        local cam = workspace.CurrentCamera
        if not cam then return end
        if glass.Parent ~= cam then glass.Parent = cam end
        local pos, sz = main.AbsolutePosition, main.AbsoluteSize
        local d = 0.95
        local tl = cam:ScreenPointToRay(pos.X, pos.Y, d).Origin
        local tr = cam:ScreenPointToRay(pos.X + sz.X, pos.Y, d).Origin
        local bl = cam:ScreenPointToRay(pos.X, pos.Y + sz.Y, d).Origin
        local br = cam:ScreenPointToRay(pos.X + sz.X, pos.Y + sz.Y, d).Origin
        glass.Size = Vector3.new(math.max((tr - tl).Magnitude, 0.01), math.max((bl - tl).Magnitude, 0.01), 0.001)
        glass.CFrame = CFrame.fromMatrix((tl + br) / 2, cam.CFrame.RightVector, cam.CFrame.UpVector)
    end)
    local function setBlur(on, dur)
        dur = dur or 0.4
        blurOn = on and blurEnabled
        if blurOn then
            local cam = workspace.CurrentCamera
            if cam then glass.Parent = cam end
        else
            task.delay(dur + 0.05, function()
                if not blurOn then glass.Parent = nil end
            end)
        end
        tw(dof, { NearIntensity = blurOn and 1 or 0 }, dur, ES.Sine)
    end

    local destroyCallbacks = {}
    gui.Destroying:Connect(function()
        for _, fn in ipairs(destroyCallbacks) do pcall(fn) end
        for _, c in ipairs(conns) do pcall(function() c:Disconnect() end) end
        pcall(function() RunService:UnbindFromRenderStep("LumenGlass") end)
        dof:Destroy()
        glass:Destroy()
    end)

    --// Header ------------------------------------------------------------------
    local top = new("Frame", { Size = UDim2.new(1, 0, 0, 48), BackgroundTransparency = 1, Parent = body })

    local logo = new("Frame", {
        Size = UDim2.fromOffset(26, 26), AnchorPoint = Vector2.new(0, 0.5),
        Position = UDim2.new(0, 16, 0, 24), BackgroundColor3 = Theme.Accent,
        BorderSizePixel = 0, Parent = top,
    }, { corner(8) })
    label({
        Text = string.upper(titleText:sub(1, 2)), Font = Enum.Font.GothamBold, TextSize = 11,
        TextColor3 = Theme.Bg, TextXAlignment = Enum.TextXAlignment.Center,
        Size = UDim2.fromScale(1, 1), Parent = logo,
    })
    onAccent(function() logo.BackgroundColor3 = Theme.Accent end)

    local titleW = textWidth(titleText, 14, Enum.Font.GothamBold)
    label({
        Text = titleText, Font = Enum.Font.GothamBold, TextSize = 14,
        Position = UDim2.fromOffset(52, 0), Size = UDim2.fromOffset(titleW + 4, 48), Parent = top,
    })
    if opts.Subtitle then
        label({
            Text = opts.Subtitle, TextColor3 = Theme.Sub, TextSize = 11,
            Position = UDim2.fromOffset(52 + titleW + 10, 1), Size = UDim2.fromOffset(80, 48), Parent = top,
        })
    end

    local function headerButton(xOffset, iconName, isDash)
        local b = new("TextButton", {
            Size = UDim2.fromOffset(28, 28), AnchorPoint = Vector2.new(1, 0.5),
            Position = UDim2.new(1, xOffset, 0, 24), BackgroundColor3 = Theme.Hover,
            BackgroundTransparency = 1, Text = "", AutoButtonColor = false, Parent = top,
        }, { circle() })
        local ic
        if isDash then
            ic = new("Frame", {
                Size = UDim2.fromOffset(11, 2), AnchorPoint = Vector2.new(0.5, 0.5),
                Position = UDim2.fromScale(0.5, 0.5), BackgroundColor3 = Theme.Sub,
                BorderSizePixel = 0, Parent = b,
            }, { corner(1) })
        else
            ic = makeIcon(b, iconName, 12, Theme.Sub)
        end
        b.MouseEnter:Connect(function()
            tw(b, { BackgroundTransparency = 0.2 }, 0.25)
            if isDash then tw(ic, { BackgroundColor3 = Theme.Text }, 0.25) else iconColor(ic, Theme.Text) end
        end)
        b.MouseLeave:Connect(function()
            tw(b, { BackgroundTransparency = 1 }, 0.25)
            if isDash then tw(ic, { BackgroundColor3 = Theme.Sub }, 0.25) else iconColor(ic, Theme.Sub) end
        end)
        return b
    end
    local closeBtn = headerButton(-14, "close", false)
    local hideBtn = headerButton(-48, nil, true)
    hideBtn.MouseButton1Click:Connect(function() setVisible(false) end)

    -- pill tab bar (center)
    local tabBar = new("Frame", {
        AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(0.5, 0, 0, 24),
        Size = UDim2.fromOffset(8, 36), BackgroundColor3 = Theme.Element,
        BackgroundTransparency = 0.4, BorderSizePixel = 0, Parent = top,
    }, { circle(), stroke(Theme.Stroke, 1, 0.5) })
    local indicator = new("Frame", {
        Size = UDim2.fromOffset(0, 28), Position = UDim2.fromOffset(4, 4),
        BackgroundColor3 = Theme.Hover, BorderSizePixel = 0, Parent = tabBar,
    }, { circle(), stroke(Theme.Stroke, 1, 0.3) })

    -- header divider that fades out at both ends
    new("Frame", {
        Size = UDim2.new(1, 0, 0, 1), Position = UDim2.fromOffset(0, 48),
        BackgroundColor3 = Theme.Stroke, BorderSizePixel = 0, Parent = body,
    }, { new("UIGradient", { Transparency = NumberSequence.new({
        NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(0.15, 0.3),
        NumberSequenceKeypoint.new(0.85, 0.3), NumberSequenceKeypoint.new(1, 1),
    }) }) })

    local content = new("Frame", {
        Size = UDim2.new(1, 0, 1, -49), Position = UDim2.fromOffset(0, 49),
        BackgroundTransparency = 1, ClipsDescendants = true, Parent = body,
    })

    -- dragging (eased follow)
    local dragging, dragStart, startPos = false, nil, nil
    top.InputBegan:Connect(function(i)
        if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then
            dragging, dragStart, startPos = true, i.Position, main.Position
            i.Changed:Connect(function()
                if i.UserInputState == Enum.UserInputState.End then dragging = false end
            end)
        end
    end)
    connect(UIS.InputChanged, function(i)
        if dragging and (i.UserInputType == Enum.UserInputType.MouseMovement or i.UserInputType == Enum.UserInputType.Touch) then
            local d = i.Position - dragStart
            tw(main, {
                Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + d.X, startPos.Y.Scale, startPos.Y.Offset + d.Y),
            }, 0.25, ES.Quint)
        end
    end)

    connect(UIS.InputBegan, function(i, gp)
        if not gp and i.KeyCode == toggleKey then setVisible(not visible) end
    end)

    --// Notifications ---------------------------------------------------------
    local holder = new("Frame", {
        Size = UDim2.new(0, 320, 1, -32), AnchorPoint = Vector2.new(1, 1),
        Position = UDim2.new(1, -16, 1, -16), BackgroundTransparency = 1, Parent = gui,
    }, {
        new("UIListLayout", {
            Padding = UDim.new(0, 8), VerticalAlignment = Enum.VerticalAlignment.Bottom,
            HorizontalAlignment = Enum.HorizontalAlignment.Right, SortOrder = Enum.SortOrder.LayoutOrder,
        }),
    })
    local notifyOrder = 0

    local Window = {}
    local tabs = {}
    Lumen._window = Window
    Window.Gui = gui
    function Window:OnDestroy(fn) table.insert(destroyCallbacks, fn) end

    function Window:Notify(o)
        if destroying then return end
        if type(o) == "string" then o = { Content = o } end
        if not ready then -- wait until the intro has finished
            task.spawn(function()
                repeat task.wait(0.1) until ready or destroying or not gui.Parent
                if gui.Parent and not destroying then Window:Notify(o) end
            end)
            return
        end
        local dur = o.Duration or 4
        local ntype = o.Type or "info"
        local tint = NOTIFY_TINT[ntype]
        local W = 300
        local title = o.Title or titleText
        local text = o.Content or o.Text or ""
        local textH = (text == "") and 0 or TextService:GetTextSize(text, 12, Enum.Font.Gotham, Vector2.new(W - 74, 1000)).Y
        local H = math.max(66, 12 + 16 + 4 + textH + 24)

        notifyOrder += 1
        local cont = new("Frame", {
            Size = UDim2.fromOffset(W, 0), BackgroundTransparency = 1,
            LayoutOrder = notifyOrder, Parent = holder,
        })
        local card = new("CanvasGroup", {
            Size = UDim2.fromOffset(W, H), Position = UDim2.new(0, 60, 0, 0),
            BackgroundColor3 = Theme.Panel, BackgroundTransparency = 0.05,
            BorderSizePixel = 0, GroupTransparency = 1, Parent = cont,
        }, { corner(12) })
        new("Frame", { -- inset border
            Size = UDim2.new(1, -2, 1, -2), Position = UDim2.fromOffset(1, 1),
            BackgroundTransparency = 1, BorderSizePixel = 0, Parent = card,
        }, { corner(11), stroke(Theme.Stroke, 1, 0.2) })

        local badge = new("Frame", {
            Size = UDim2.fromOffset(32, 32), Position = UDim2.fromOffset(14, 14),
            BackgroundColor3 = (ntype == "success") and Theme.Text or Theme.Element,
            BorderSizePixel = 0, Parent = card,
        }, { circle() })
        makeIcon(badge, o.Icon or NOTIFY_ICON[ntype] or "bolt", 14,
            (ntype == "success") and Theme.Bg or (tint or Theme.Text))

        local titleL = label({
            Text = title, Font = Enum.Font.GothamBold, TextSize = 13,
            Position = UDim2.fromOffset(58, 12), Size = UDim2.new(1, -70, 0, 16), Parent = card,
        })
        local textL = label({
            Text = text, Font = Enum.Font.Gotham, TextColor3 = Theme.Sub, TextSize = 12, TextWrapped = true,
            TextYAlignment = Enum.TextYAlignment.Top,
            Position = UDim2.fromOffset(58, 31), Size = UDim2.new(1, -70, 0, textH), Parent = card,
        })
        local track = new("Frame", {
            Size = UDim2.new(1, -28, 0, 2), Position = UDim2.new(0, 14, 1, -10),
            BackgroundColor3 = Theme.Hover, BorderSizePixel = 0, Parent = card,
        }, { circle() })
        local fill = new("Frame", {
            Size = UDim2.fromScale(1, 1), BackgroundColor3 = tint or Theme.Accent,
            BorderSizePixel = 0, Parent = track,
        }, { circle() })
        local hit = new("TextButton", {
            Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, Text = "",
            AutoButtonColor = false, ZIndex = 5, Parent = card,
        })

        local dismissed = false
        local function dismiss()
            if dismissed then return end
            dismissed = true
            tw(card, { Position = UDim2.new(0, 80, 0, 0), GroupTransparency = 1 }, 0.45, ES.Quint)
            task.wait(0.35)
            tw(cont, { Size = UDim2.fromOffset(W, 0) }, 0.3, ES.Quint)
            task.wait(0.35)
            cont:Destroy()
        end
        hit.MouseButton1Click:Connect(dismiss)

        pcall(function() titleL.MaxVisibleGraphemes = 0 textL.MaxVisibleGraphemes = 0 end)
        tw(cont, { Size = UDim2.fromOffset(W, H) }, 0.35, ES.Quint)
        task.delay(0.1, function()
            tw(card, { Position = UDim2.new(0, 0, 0, 0), GroupTransparency = 0 }, 0.6, ES.Quint)
        end)
        tw(fill, { Size = UDim2.fromScale(0, 1) }, dur, ES.Linear)
        -- text animation: title types first, then the body
        task.spawn(function()
            task.wait(0.3)
            typewrite(titleL, 45)
            typewrite(textL, 80)
        end)
        task.delay(dur, dismiss)
    end

    function Lumen:Notify(o)
        if Lumen._window then Lumen._window:Notify(o) end
    end

    --// show / hide / destroy (all animated) -----------------------------------
    local hintShown = false
    local pill -- info bar, defined below

    -- accent line at the window's center (used to draw / fold the window)
    local function makeLine(startWidth)
        local line = new("Frame", {
            Size = UDim2.fromOffset(startWidth, 2), AnchorPoint = Vector2.new(0.5, 0.5),
            Position = main.Position, BackgroundColor3 = Theme.Accent,
            BorderSizePixel = 0, ZIndex = 10, Parent = gui,
        }, { circle() })
        return line
    end

    -- appear: a line is drawn across the center, then the window unfolds from it
    local function unfold()
        local W = size.X.Offset
        local lineW = W * userScale
        local line = makeLine(0)
        tw(line, { Size = UDim2.fromOffset(lineW, 2) }, 0.5, ES.Quart)
        task.wait(0.55)
        if destroying or not gui.Parent then line:Destroy() return end
        scale.Scale = userScale
        main.GroupTransparency = 0
        main.Size = UDim2.fromOffset(W, 2)
        main.Position = line.Position
        main.Visible = true
        setBlur(true, 0.8)
        tw(main, { Size = size }, 0.8, ES.Quint)
        tw(line, { BackgroundTransparency = 1 }, 0.4, ES.Sine)
        task.delay(0.45, function() line:Destroy() end)
        task.wait(0.8)
    end

    -- disappear: the same thing in reverse (window folds into a line, the line shrinks away)
    local function fold()
        local W = size.X.Offset
        setBlur(false, 0.6)
        tw(main, { Size = UDim2.fromOffset(W, 2) }, 0.6, ES.Quint)
        task.wait(0.6)
        if destroying or not gui.Parent then return end
        local line = makeLine(W * userScale)
        line.BackgroundTransparency = 1
        tw(line, { BackgroundTransparency = 0 }, 0.12, ES.Sine)
        task.wait(0.08)
        main.Visible = false
        main.Size = size
        tw(line, { Size = UDim2.fromOffset(0, 2) }, 0.5, ES.Quint)
        task.delay(0.55, function() line:Destroy() end)
        task.wait(0.5)
    end

    setVisible = function(b)
        if not ready or destroying or busy or b == visible then return end
        busy = true
        visible = b
        task.spawn(function()
            if b then
                unfold()
            else
                fold()
                if not hintShown and not destroying then
                    hintShown = true
                    Window:Notify({
                        Title = titleText, Duration = 4,
                        Content = "Click the info bar or press " .. toggleKey.Name .. " to reopen.",
                    })
                end
            end
            busy = false
        end)
    end

    function Window:SetVisible(b) setVisible(b) end

    -- destroy: the window squeezes in on itself first, then the info bar closes in from both sides
    function Window:Destroy()
        if destroying then return end
        destroying = true
        ready = false
        setBlur(false, 0.5)
        for _, c in ipairs(holder:GetChildren()) do
            if c:IsA("Frame") then c:Destroy() end
        end
        task.spawn(function()
            if main.Visible then
                tw(scale, { Scale = 0.01 }, 0.6, ES.Back, ED.In)
                task.delay(0.15, function() tw(main, { GroupTransparency = 1 }, 0.4, ES.Sine) end)
                task.wait(0.55)
            end
            if pill and pill.Visible then
                local pScale = pill:FindFirstChildOfClass("UIScale")
                tw(pill, { Size = UDim2.fromOffset(40, 40) }, 0.6, ES.Quint)
                task.delay(0.4, function()
                    tw(pill, { GroupTransparency = 1 }, 0.35, ES.Sine)
                    if pScale then tw(pScale, { Scale = 0.6 }, 0.35, ES.Quint) end
                end)
                task.wait(0.8)
            end
            if Lumen._window == Window then Lumen._window = nil end
            gui:Destroy()
        end)
    end
    function Lumen:Destroy()
        if Lumen._window then Lumen._window:Destroy() end
    end
    closeBtn.MouseButton1Click:Connect(function() Window:Destroy() end)

    -- live settings (handy for test buttons)
    function Window:SetAccent(c)
        Theme.Accent = c
        for _, fn in ipairs(accentHooks) do pcall(fn) end
    end
    function Window:SetBlur(b)
        blurEnabled = b and true or false
        if visible then setBlur(true, 0.4) end
    end
    function Window:SetTransparency(n)
        tw(main, { BackgroundTransparency = math.clamp(n, 0, 1) }, 0.3)
    end
    function Window:SetScale(n)
        userScale = math.clamp(n, 0.6, 1.4)
        tw(scale, { Scale = userScale }, 0.4)
    end
    function Window:SetFPS(b)
        if not pill then return end
        if b and ready then
            pill.Visible = true
            tw(pill, { GroupTransparency = 0 }, 0.6, ES.Quint)
        else
            tw(pill, { GroupTransparency = 1 }, 0.5, ES.Quint)
            task.delay(0.55, function()
                if pill.GroupTransparency >= 0.99 then pill.Visible = false end
            end)
        end
    end
    Window.SetInfoBar = Window.SetFPS

    --// Tabs --------------------------------------------------------------------
    local current
    local barW = 4

    -- "Expand" style: every tab is an icon, the selected one grows to show its name
    local function layoutTabs(instant)
        local x = 4
        local dur = instant and 0 or 0.5
        for _, tb in ipairs(tabs) do
            local w = (tb == current) and (38 + tb.TextW + 10) or 36
            tb.X, tb.W = x, w
            tw(tb.Btn, { Position = UDim2.fromOffset(x, 4), Size = UDim2.fromOffset(w, 28) }, dur)
            tw(tb.Label, { TextTransparency = (tb == current) and 0 or 1 }, instant and 0 or 0.35)
            x += w + 4
        end
        barW = x
        tw(tabBar, { Size = UDim2.fromOffset(x, 36) }, dur)
    end
    local function selectTab(tab, instant)
        if current == tab then return end
        local prev = current
        current = tab
        local dir = 0
        if prev then dir = (tab.Index > prev.Index) and 1 or -1 end

        if expandTabs then layoutTabs(instant) end
        tw(indicator, {
            Position = UDim2.fromOffset(tab.X, 4), Size = UDim2.fromOffset(tab.W, 28),
        }, instant and 0 or 0.55, ES.Quint)

        for _, t in ipairs(tabs) do
            local on = (t == tab)
            t.Active = on
            tw(t.Label, { TextColor3 = on and Theme.Text or Theme.Sub }, 0.3)
            if t.Icon then iconColor(t.Icon, on and Theme.Accent or Theme.Sub, 0.3) end
        end

        if prev then
            tw(prev.Page, { GroupTransparency = 1, Position = UDim2.fromOffset(-dir * 24, 0) }, 0.28, ES.Quint)
            task.delay(0.3, function()
                if current ~= prev then prev.Page.Visible = false end
            end)
        end
        tab.Page.Visible = true
        if instant then
            tab.Page.Position = UDim2.fromOffset(0, 0)
            tab.Page.GroupTransparency = 0
        else
            tab.Page.Position = UDim2.fromOffset(dir * 24, 0)
            tab.Page.GroupTransparency = 1
            tw(tab.Page, { GroupTransparency = 0, Position = UDim2.fromOffset(0, 0) }, 0.55, ES.Quint)
        end
    end

    function Window:CreateTab(name, icon)
        if type(name) == "table" then return Window:AddTab(name) end
        return Window:AddTab({ Name = name, Icon = icon })
    end

    function Window:AddTab(o)
        if type(o) == "string" then o = { Name = o } end
        o = o or {}
        local name = o.Name or "Tab"
        local iconName = o.Icon or o.Image
        if expandTabs and not iconName then iconName = name end

        local tw_ = textWidth(name, 13)
        local iconW = iconName and 20 or 0
        local w = math.floor(tw_ + iconW + 30)
        if expandTabs then w = 36 end
        local x = barW
        barW = barW + w + 4
        tabBar.Size = UDim2.fromOffset(barW, 36)

        local btn = new("TextButton", {
            Size = UDim2.fromOffset(w, 28), Position = UDim2.fromOffset(x, 4),
            BackgroundTransparency = 1, Text = "", AutoButtonColor = false, Parent = tabBar,
        })
        local icon
        if iconName then
            local holderI = new("Frame", {
                Size = UDim2.fromOffset(16, 16), Position = UDim2.fromOffset(11, 6),
                BackgroundTransparency = 1, Parent = btn,
            })
            icon = makeIcon(holderI, iconName, 13, Theme.Sub)
        end
        local lbl = label({
            Text = name, TextColor3 = Theme.Sub,
            Position = UDim2.fromOffset(13 + iconW, 0), Size = UDim2.fromOffset(tw_ + 6, 28), Parent = btn,
        })
        if expandTabs then lbl.TextTransparency = 1 end

        local pageG = new("CanvasGroup", {
            Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, BorderSizePixel = 0,
            GroupTransparency = 1, Visible = false, Parent = content,
        })
        local page = new("ScrollingFrame", {
            Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, BorderSizePixel = 0,
            ScrollBarThickness = 2, ScrollBarImageColor3 = Theme.Stroke,
            CanvasSize = UDim2.new(), AutomaticCanvasSize = Enum.AutomaticSize.Y,
            Parent = pageG,
        }, {
            new("UIListLayout", { Padding = UDim.new(0, 8), SortOrder = Enum.SortOrder.LayoutOrder }),
            pad(18, 14, 18, 16),
        })

        local tab = {
            Btn = btn, Label = lbl, Icon = icon, Page = pageG, Name = name,
            X = x, W = w, Index = #tabs + 1, TextW = tw_,
        }
        tabs[#tabs + 1] = tab
        onAccent(function()
            if tab.Active and tab.Icon then setIconColor(tab.Icon, Theme.Accent) end
        end)

        btn.MouseEnter:Connect(function()
            if not tab.Active then
                tw(lbl, { TextColor3 = Theme.Text }, 0.25)
                if icon then iconColor(icon, Theme.Text, 0.25) end
            end
        end)
        btn.MouseLeave:Connect(function()
            if not tab.Active then
                tw(lbl, { TextColor3 = Theme.Sub }, 0.25)
                if icon then iconColor(icon, Theme.Sub, 0.25) end
            end
        end)
        btn.MouseButton1Click:Connect(function() selectTab(tab) end)

        local order = 0
        local function nextOrder() order += 1 return order end

        local function box(height)
            return new("Frame", {
                Size = UDim2.new(1, 0, 0, height), BackgroundColor3 = Theme.Element,
                BackgroundTransparency = 0.35, BorderSizePixel = 0, ClipsDescendants = true,
                LayoutOrder = nextOrder(), Parent = page,
            }, { corner(10), stroke(Theme.Stroke, 1, 0.4) })
        end

        local function hoverable(frame, hit)
            local st = frame:FindFirstChildOfClass("UIStroke")
            hit.MouseEnter:Connect(function()
                tw(frame, { BackgroundColor3 = Theme.Hover, BackgroundTransparency = 0.15 }, 0.35)
                if st then tw(st, { Transparency = 0.1 }, 0.35) end
            end)
            hit.MouseLeave:Connect(function()
                tw(frame, { BackgroundColor3 = Theme.Element, BackgroundTransparency = 0.35 }, 0.35)
                if st then tw(st, { Transparency = 0.4 }, 0.35) end
            end)
        end

        local function cardIcon(f, name, cy)
            if not name then return 0 end
            local hld = new("Frame", {
                Size = UDim2.fromOffset(20, 20), AnchorPoint = Vector2.new(0, 0.5),
                Position = UDim2.new(0, 12, 0, cy or 20), BackgroundTransparency = 1, Parent = f,
            })
            makeIcon(hld, name, 15, Theme.Sub)
            return 28
        end

        local function hitButton(parentFrame, h)
            return new("TextButton", {
                Size = UDim2.new(1, 0, 0, h or 40), BackgroundTransparency = 1,
                Text = "", AutoButtonColor = false, Parent = parentFrame,
            })
        end

        local function register(o2, obj)
            if o2.Flag then Lumen.Flags[o2.Flag] = obj end
        end

        local function ripple(frame)
            local m = UIS:GetMouseLocation()
            local rel = (Vector2.new(m.X, m.Y) - frame.AbsolutePosition) / math.max(scale.Scale, 0.01)
            local d = math.max(frame.AbsoluteSize.X / math.max(scale.Scale, 0.01), 80) * 2.2
            local r = new("Frame", {
                Size = UDim2.fromOffset(0, 0), AnchorPoint = Vector2.new(0.5, 0.5),
                Position = UDim2.fromOffset(rel.X, rel.Y), BackgroundColor3 = Color3.new(1, 1, 1),
                BackgroundTransparency = 0.88, BorderSizePixel = 0, Parent = frame,
            }, { circle() })
            tw(r, { Size = UDim2.fromOffset(d, d), BackgroundTransparency = 1 }, 0.7, ES.Quint)
            task.delay(0.75, function() r:Destroy() end)
        end

        local Tab = {}

        function Tab:CreateSection(text)
            text = string.upper(text or "Section")
            local tW = textWidth(text, 11, Enum.Font.GothamBold)
            local f = new("Frame", {
                Size = UDim2.new(1, 0, 0, 26), BackgroundTransparency = 1,
                LayoutOrder = nextOrder(), Parent = page,
            })
            label({
                Text = text, Font = Enum.Font.GothamBold, TextSize = 11, TextColor3 = Theme.Sub,
                TextYAlignment = Enum.TextYAlignment.Bottom,
                Size = UDim2.fromOffset(tW + 4, 22), Parent = f,
            })
            new("Frame", {
                Size = UDim2.new(1, -(tW + 14), 0, 1), Position = UDim2.new(0, tW + 12, 0, 16),
                BackgroundColor3 = Theme.Stroke, BackgroundTransparency = 0.4,
                BorderSizePixel = 0, Parent = f,
            })
        end

        function Tab:CreateLabel(text)
            local l = label({
                Text = text or "", TextColor3 = Theme.Sub, TextSize = 12, Font = Enum.Font.Gotham,
                TextWrapped = true, AutomaticSize = Enum.AutomaticSize.Y,
                Size = UDim2.new(1, 0, 0, 18), LayoutOrder = nextOrder(), Parent = page,
            })
            return { Set = function(_, t) l.Text = t end }
        end

        function Tab:CreateParagraph(o2)
            local f = new("Frame", {
                Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y,
                BackgroundColor3 = Theme.Element, BackgroundTransparency = 0.35,
                BorderSizePixel = 0, LayoutOrder = nextOrder(), Parent = page,
            }, {
                corner(10), stroke(Theme.Stroke, 1, 0.4), pad(14, 12, 14, 12),
                new("UIListLayout", { Padding = UDim.new(0, 5), SortOrder = Enum.SortOrder.LayoutOrder }),
            })
            local t = label({
                Text = o2.Title or "", Font = Enum.Font.GothamBold,
                Size = UDim2.new(1, 0, 0, 16), LayoutOrder = 1, Parent = f,
            })
            local c = label({
                Text = o2.Content or "", Font = Enum.Font.Gotham, TextColor3 = Theme.Sub, TextSize = 12,
                TextWrapped = true, AutomaticSize = Enum.AutomaticSize.Y, Size = UDim2.new(1, 0, 0, 14),
                TextYAlignment = Enum.TextYAlignment.Top, LayoutOrder = 2, Parent = f,
            })
            return {
                Set = function(_, n)
                    if n.Title then t.Text = n.Title end
                    if n.Content then c.Text = n.Content end
                end,
            }
        end

        function Tab:CreateButton(o2)
            local f = box(40)
            local io = cardIcon(f, o2.Icon, 20)
            local hit = hitButton(f)
            label({
                Text = o2.Name or "Button", Position = UDim2.fromOffset(14 + io, 0),
                Size = UDim2.new(1, -50, 1, 0), Parent = f,
            })
            local ih = new("Frame", {
                Size = UDim2.fromOffset(20, 20), AnchorPoint = Vector2.new(1, 0.5),
                Position = UDim2.new(1, -12, 0.5, 0), BackgroundTransparency = 1,
                Rotation = -90, Parent = f,
            })
            local arrow = makeIcon(ih, "chevron", 12, Theme.Sub)
            hit.MouseEnter:Connect(function()
                iconColor(arrow, Theme.Accent)
                tw(ih, { Position = UDim2.new(1, -8, 0.5, 0) }, 0.35)
            end)
            hit.MouseLeave:Connect(function()
                iconColor(arrow, Theme.Sub)
                tw(ih, { Position = UDim2.new(1, -12, 0.5, 0) }, 0.35)
            end)
            hoverable(f, hit)
            hit.MouseButton1Click:Connect(function()
                ripple(f)
                safe(o2.Callback)
            end)
            return { Fire = function() safe(o2.Callback) end }
        end

        function Tab:CreateToggle(o2)
            local f = box(40)
            local io = cardIcon(f, o2.Icon, 20)
            local hit = hitButton(f)
            label({
                Text = o2.Name or "Toggle", Position = UDim2.fromOffset(14 + io, 0),
                Size = UDim2.new(1, -70, 1, 0), Parent = f,
            })
            local track = new("Frame", {
                Size = UDim2.fromOffset(40, 22), AnchorPoint = Vector2.new(1, 0.5),
                Position = UDim2.new(1, -14, 0.5, 0), BackgroundColor3 = Theme.Hover,
                BorderSizePixel = 0, Parent = f,
            }, { circle(), stroke(Theme.Stroke, 1, 0.3) })
            local knob = new("Frame", {
                Size = UDim2.fromOffset(16, 16), AnchorPoint = Vector2.new(0, 0.5),
                Position = UDim2.new(0, 3, 0.5, 0), BackgroundColor3 = Theme.Sub,
                BorderSizePixel = 0, Parent = track,
            }, { circle() })

            local value = false
            if o2.CurrentValue ~= nil then value = o2.CurrentValue == true
            elseif o2.Default ~= nil then value = o2.Default == true end

            local obj = { Type = "Toggle", CurrentValue = value, Flag = o2.Flag }
            local function render(animate)
                local t = animate and 0.45 or 0
                tw(track, { BackgroundColor3 = value and Theme.Accent or Theme.Hover }, t)
                tw(knob, {
                    Position = value and UDim2.new(0, 21, 0.5, 0) or UDim2.new(0, 3, 0.5, 0),
                    BackgroundColor3 = value and Theme.Bg or Theme.Sub,
                }, t)
                if animate then -- the knob stretches while it travels
                    tw(knob, { Size = UDim2.fromOffset(22, 16) }, 0.14)
                    task.delay(0.14, function() tw(knob, { Size = UDim2.fromOffset(16, 16) }, 0.35) end)
                end
            end
            function obj:Set(v, silent)
                value = v and true or false
                obj.CurrentValue = value
                render(true)
                if not silent then safe(o2.Callback, value) end
                saveConfig()
            end
            function obj:Get() return value end
            render(false)
            onAccent(function() render(false) end)
            hoverable(f, hit)
            hit.MouseButton1Click:Connect(function() obj:Set(not value) end)
            register(o2, obj)
            return obj
        end

        function Tab:CreateSlider(o2)
            local min = (o2.Range and o2.Range[1]) or o2.Min or 0
            local max = (o2.Range and o2.Range[2]) or o2.Max or 100
            local inc = o2.Increment or 1
            local decimals = #(tostring(inc):match("%.(%d+)") or "")
            local obj = { Type = "Slider", Flag = o2.Flag }
            local value
            local f = box(56)
            local io = cardIcon(f, o2.Icon, 18)
            label({
                Text = o2.Name or "Slider", Position = UDim2.fromOffset(14 + io, 9),
                Size = UDim2.new(1, -120, 0, 18), Parent = f,
            })
            local valL = label({
                Text = "", TextColor3 = Theme.Sub, TextSize = 12,
                TextXAlignment = Enum.TextXAlignment.Right, AnchorPoint = Vector2.new(1, 0),
                Position = UDim2.new(1, -14, 0, 9), Size = UDim2.fromOffset(100, 18), Parent = f,
            })
            local bar = new("Frame", {
                Size = UDim2.new(1, -28, 0, 6), Position = UDim2.fromOffset(14, 38),
                BackgroundColor3 = Theme.Hover, BorderSizePixel = 0, ClipsDescendants = false, Parent = f,
            }, { circle() })
            local fill = new("Frame", {
                Size = UDim2.fromScale(0, 1), BackgroundColor3 = Theme.Accent,
                BorderSizePixel = 0, Parent = bar,
            }, { circle() })
            local knob = new("Frame", {
                Size = UDim2.fromOffset(14, 14), AnchorPoint = Vector2.new(0.5, 0.5),
                Position = UDim2.fromScale(0, 0.5), BackgroundColor3 = Color3.new(1, 1, 1),
                BorderSizePixel = 0, ZIndex = 3, Parent = bar,
            }, { circle(), stroke(Color3.new(0, 0, 0), 1, 0.7) })
            onAccent(function() fill.BackgroundColor3 = Theme.Accent end)

            local function setValue(v, fire, instant)
                v = math.floor((v - min) / inc + 0.5) * inc + min
                v = math.clamp(v, min, max)
                if decimals > 0 then v = tonumber(string.format("%." .. decimals .. "f", v)) end
                local changed = (v ~= value)
                value = v
                obj.CurrentValue = v
                local rel = (max == min) and 0 or (v - min) / (max - min)
                if instant then
                    fill.Size = UDim2.fromScale(rel, 1)
                    knob.Position = UDim2.fromScale(rel, 0.5)
                else
                    tw(fill, { Size = UDim2.fromScale(rel, 1) }, 0.25)
                    tw(knob, { Position = UDim2.fromScale(rel, 0.5) }, 0.25)
                end
                valL.Text = tostring(v) .. (o2.Suffix and (" " .. o2.Suffix) or "")
                if fire and changed then
                    safe(o2.Callback, v)
                    saveConfig()
                end
            end
            setValue(o2.CurrentValue or o2.Default or min, false, true)

            local hit = new("TextButton", {
                Size = UDim2.new(1, 0, 0, 30), Position = UDim2.fromOffset(0, 26),
                BackgroundTransparency = 1, Text = "", AutoButtonColor = false, Parent = f,
            })
            local sliding, hovering = false, false
            local function knobSize()
                tw(knob, { Size = (sliding or hovering) and UDim2.fromOffset(18, 18) or UDim2.fromOffset(14, 14) }, 0.3, ES.Back)
            end
            local function fromX(x)
                local rel = math.clamp((x - bar.AbsolutePosition.X) / math.max(bar.AbsoluteSize.X, 1), 0, 1)
                setValue(min + (max - min) * rel, true)
            end
            hit.InputBegan:Connect(function(i)
                if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then
                    sliding = true
                    knobSize()
                    fromX(i.Position.X)
                end
            end)
            hit.MouseEnter:Connect(function() hovering = true knobSize() end)
            hit.MouseLeave:Connect(function() hovering = false knobSize() end)
            connect(UIS.InputChanged, function(i)
                if sliding and (i.UserInputType == Enum.UserInputType.MouseMovement or i.UserInputType == Enum.UserInputType.Touch) then
                    fromX(i.Position.X)
                end
            end)
            connect(UIS.InputEnded, function(i)
                if (i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch) and sliding then
                    sliding = false
                    knobSize()
                end
            end)
            local st = f:FindFirstChildOfClass("UIStroke")
            f.MouseEnter:Connect(function() if st then tw(st, { Transparency = 0.1 }, 0.35) end end)
            f.MouseLeave:Connect(function() if st then tw(st, { Transparency = 0.4 }, 0.35) end end)
            function obj:Set(v, silent) setValue(tonumber(v) or min, not silent) end
            function obj:Get() return value end
            register(o2, obj)
            return obj
        end

        function Tab:CreateDropdown(o2)
            local options = o2.Options or {}
            local multi = o2.MultipleOptions == true
            local selected = {}
            local init = o2.CurrentOption
            if init == nil then init = o2.Default end
            if type(init) == "table" then
                for _, v in ipairs(init) do table.insert(selected, v) end
            elseif init ~= nil then
                selected[1] = init
            end
            if not multi and #selected > 1 then selected = { selected[1] } end

            local obj = { Type = "Dropdown", CurrentOption = selected, Flag = o2.Flag }
            local open = false
            local f = box(40)
            local io = cardIcon(f, o2.Icon, 20)

            local head = hitButton(f, 40)
            label({
                Text = o2.Name or "Dropdown", Position = UDim2.fromOffset(14 + io, 0),
                Size = UDim2.new(0.5, -14, 1, 0), Parent = head,
            })
            local selL = label({
                Text = "", TextColor3 = Theme.Sub, TextSize = 12,
                TextXAlignment = Enum.TextXAlignment.Right, TextTruncate = Enum.TextTruncate.AtEnd,
                AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, -38, 0, 0),
                Size = UDim2.new(0.5, -44, 1, 0), Parent = head,
            })
            local chev = new("Frame", {
                Size = UDim2.fromOffset(20, 20), AnchorPoint = Vector2.new(1, 0.5),
                Position = UDim2.new(1, -12, 0.5, 0), BackgroundTransparency = 1, Parent = head,
            })
            makeIcon(chev, "chevron", 12, Theme.Sub)

            local list = new("ScrollingFrame", {
                Position = UDim2.fromOffset(0, 40), Size = UDim2.new(1, 0, 1, -40),
                BackgroundTransparency = 1, BorderSizePixel = 0, ScrollBarThickness = 2,
                ScrollBarImageColor3 = Theme.Stroke, CanvasSize = UDim2.new(),
                AutomaticCanvasSize = Enum.AutomaticSize.Y, Parent = f,
            }, {
                new("UIListLayout", { Padding = UDim.new(0, 2), SortOrder = Enum.SortOrder.LayoutOrder }),
                pad(6, 2, 6, 6),
            })

            local function summary()
                if #selected == 0 then return "None"
                elseif #selected == 1 then return tostring(selected[1])
                else return "Various (" .. #selected .. ")" end
            end
            local function openHeight()
                local shown = math.min(#options, 6)
                return 40 + 8 + shown * 28 + math.max(shown - 1, 0) * 2
            end

            local rebuild
            local function setOpen(b)
                open = b
                tw(f, { Size = UDim2.new(1, 0, 0, b and openHeight() or 40) }, 0.45)
                tw(chev, { Rotation = b and 180 or 0 }, 0.45)
                if b then -- options fade in one after another
                    for idx, c in ipairs(list:GetChildren()) do
                        if c:IsA("TextButton") then
                            local l = c:FindFirstChildOfClass("TextLabel")
                            if l then
                                l.TextTransparency = 1
                                task.delay((c.LayoutOrder - 1) * 0.03, function()
                                    tw(l, { TextTransparency = 0 }, 0.35)
                                end)
                            end
                        end
                    end
                end
            end

            local function fire(silent)
                obj.CurrentOption = selected
                selL.Text = summary()
                rebuild()
                if not silent then safe(o2.Callback, selected) end
                saveConfig()
            end
            local function choose(opt)
                if multi then
                    local idx = table.find(selected, opt)
                    if idx then table.remove(selected, idx) else table.insert(selected, opt) end
                else
                    selected = { opt }
                    setOpen(false)
                end
                fire(false)
            end

            rebuild = function()
                for _, c in ipairs(list:GetChildren()) do
                    if c:IsA("TextButton") then c:Destroy() end
                end
                for idx, opt in ipairs(options) do
                    local isSel = table.find(selected, opt) ~= nil
                    local ob = new("TextButton", {
                        Size = UDim2.new(1, 0, 0, 28), BackgroundColor3 = Theme.Hover,
                        BackgroundTransparency = 1, Text = "", AutoButtonColor = false,
                        LayoutOrder = idx, Parent = list,
                    }, { corner(7) })
                    label({
                        Text = tostring(opt), Position = UDim2.fromOffset(10, 0),
                        Size = UDim2.new(1, -36, 1, 0),
                        TextColor3 = isSel and Theme.Accent or Theme.Text, Parent = ob,
                    })
                    if isSel then
                        local h = new("Frame", {
                            Size = UDim2.fromOffset(16, 16), AnchorPoint = Vector2.new(1, 0.5),
                            Position = UDim2.new(1, -6, 0.5, 0), BackgroundTransparency = 1, Parent = ob,
                        })
                        makeIcon(h, "check", 11, Theme.Accent)
                    end
                    ob.MouseEnter:Connect(function() tw(ob, { BackgroundTransparency = 0.2 }, 0.25) end)
                    ob.MouseLeave:Connect(function() tw(ob, { BackgroundTransparency = 1 }, 0.25) end)
                    ob.MouseButton1Click:Connect(function() choose(opt) end)
                end
                if open then f.Size = UDim2.new(1, 0, 0, openHeight()) end
            end

            function obj:Set(v, silent)
                selected = {}
                if type(v) == "table" then
                    for _, x in ipairs(v) do table.insert(selected, x) end
                elseif v ~= nil then
                    selected[1] = v
                end
                if not multi and #selected > 1 then selected = { selected[1] } end
                fire(silent)
            end
            function obj:Get() return selected end
            function obj:Refresh(newOptions, keep)
                options = newOptions or {}
                if not keep then selected = {} end
                obj.CurrentOption = selected
                selL.Text = summary()
                rebuild()
            end

            selL.Text = summary()
            rebuild()
            onAccent(function() rebuild() end)
            hoverable(f, head)
            head.MouseButton1Click:Connect(function() setOpen(not open) end)
            register(o2, obj)
            return obj
        end

        function Tab:CreateInput(o2)
            local f = box(40)
            local io = cardIcon(f, o2.Icon, 20)
            label({
                Text = o2.Name or "Input", Position = UDim2.fromOffset(14 + io, 0),
                Size = UDim2.new(1, -190, 1, 0), Parent = f,
            })
            local tb = new("TextBox", {
                Size = UDim2.fromOffset(150, 26), AnchorPoint = Vector2.new(1, 0.5),
                Position = UDim2.new(1, -10, 0.5, 0), BackgroundColor3 = Theme.Hover,
                BackgroundTransparency = 0.2, BorderSizePixel = 0,
                Text = o2.CurrentValue or o2.Default or "",
                PlaceholderText = o2.PlaceholderText or o2.Placeholder or "...",
                PlaceholderColor3 = Theme.Sub, TextColor3 = Theme.Text, Font = Enum.Font.Gotham,
                TextSize = 12, ClearTextOnFocus = false, TextXAlignment = Enum.TextXAlignment.Left,
                ClipsDescendants = true, Parent = f,
            }, { corner(8), pad(10, 0, 10, 0) })
            local underline = new("Frame", {
                Size = UDim2.new(0, 0, 0, 2), AnchorPoint = Vector2.new(0.5, 1),
                Position = UDim2.new(0.5, 0, 1, 0), BackgroundColor3 = Theme.Accent,
                BorderSizePixel = 0, Parent = tb,
            })
            onAccent(function() underline.BackgroundColor3 = Theme.Accent end)
            local obj = { Type = "Input", CurrentValue = tb.Text, Flag = o2.Flag }
            tb.Focused:Connect(function() tw(underline, { Size = UDim2.new(1, 0, 0, 2) }, 0.45) end)
            tb.FocusLost:Connect(function(enter)
                tw(underline, { Size = UDim2.new(0, 0, 0, 2) }, 0.35)
                obj.CurrentValue = tb.Text
                safe(o2.Callback, tb.Text, enter)
                if o2.RemoveTextAfterFocusLost then tb.Text = "" end
                saveConfig()
            end)
            function obj:Set(t, silent)
                tb.Text = tostring(t)
                obj.CurrentValue = tb.Text
                if not silent then safe(o2.Callback, tb.Text, false) end
                saveConfig()
            end
            function obj:Get() return tb.Text end
            register(o2, obj)
            return obj
        end

        function Tab:CreateKeybind(o2)
            local current = o2.CurrentKeybind or o2.Default or "None"
            if typeof(current) == "EnumItem" then current = current.Name end
            local listening = false
            local f = box(40)
            local io = cardIcon(f, o2.Icon, 20)
            label({
                Text = o2.Name or "Keybind", Position = UDim2.fromOffset(14 + io, 0),
                Size = UDim2.new(1, -130, 1, 0), Parent = f,
            })
            local kb = new("TextButton", {
                Size = UDim2.fromOffset(0, 26), AutomaticSize = Enum.AutomaticSize.X,
                AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -10, 0.5, 0),
                BackgroundColor3 = Theme.Hover, BackgroundTransparency = 0.2, BorderSizePixel = 0,
                Text = current, Font = Enum.Font.GothamBold, TextSize = 12, TextColor3 = Theme.Text,
                AutoButtonColor = false, Parent = f,
            }, { corner(8), pad(12, 0, 12, 0) })
            local obj = { Type = "Keybind", CurrentKeybind = current, Flag = o2.Flag }
            kb.MouseButton1Click:Connect(function()
                listening = true
                kb.Text = "..."
                tw(kb, { BackgroundTransparency = 0 }, 0.25)
            end)
            connect(UIS.InputBegan, function(i, gp)
                if listening then
                    if i.UserInputType == Enum.UserInputType.Keyboard then
                        if i.KeyCode == Enum.KeyCode.Escape then
                            listening = false
                            kb.Text = current
                            tw(kb, { BackgroundTransparency = 0.2 }, 0.25)
                        elseif i.KeyCode ~= Enum.KeyCode.Unknown and i.KeyCode ~= toggleKey then
                            current = i.KeyCode.Name
                            obj.CurrentKeybind = current
                            kb.Text = current
                            listening = false
                            tw(kb, { BackgroundTransparency = 0.2 }, 0.25)
                            saveConfig()
                        end
                    end
                    return
                end
                if gp or current == "None" then return end
                if i.UserInputType == Enum.UserInputType.Keyboard and i.KeyCode.Name == current then
                    if o2.HoldToInteract then
                        safe(o2.Callback, true)
                        local c
                        c = i.Changed:Connect(function()
                            if i.UserInputState == Enum.UserInputState.End then
                                c:Disconnect()
                                safe(o2.Callback, false)
                            end
                        end)
                    else
                        safe(o2.Callback)
                    end
                end
            end)
            hoverable(f, kb)
            function obj:Set(k)
                if typeof(k) == "EnumItem" then k = k.Name end
                current = tostring(k)
                obj.CurrentKeybind = current
                kb.Text = current
                listening = false
                saveConfig()
            end
            function obj:Get() return current end
            register(o2, obj)
            return obj
        end

        function Tab:CreateColorPicker(o2)
            local color = o2.Color or o2.Default or Color3.new(1, 1, 1)
            local h, s, v = color:ToHSV()
            local open = false
            local obj = { Type = "ColorPicker", Color = color, Flag = o2.Flag }

            local f = box(40)
            local io = cardIcon(f, o2.Icon, 20)
            local head = hitButton(f, 40)
            label({
                Text = o2.Name or "Color", Position = UDim2.fromOffset(14 + io, 0),
                Size = UDim2.new(1, -70, 1, 0), Parent = head,
            })
            local swatch = new("Frame", {
                Size = UDim2.fromOffset(32, 18), AnchorPoint = Vector2.new(1, 0.5),
                Position = UDim2.new(1, -14, 0.5, 0), BackgroundColor3 = color,
                BorderSizePixel = 0, Parent = head,
            }, { corner(6), stroke(Theme.Stroke, 1, 0) })

            local sv = new("Frame", {
                Position = UDim2.fromOffset(14, 52), Size = UDim2.fromOffset(190, 100),
                BackgroundColor3 = Color3.fromHSV(h, 1, 1), BorderSizePixel = 0, Parent = f,
            }, { corner(8) })
            new("Frame", {
                Size = UDim2.fromScale(1, 1), BackgroundColor3 = Color3.new(1, 1, 1),
                BorderSizePixel = 0, Parent = sv,
            }, { corner(8), new("UIGradient", { Transparency = NumberSequence.new(0, 1) }) })
            new("Frame", {
                Size = UDim2.fromScale(1, 1), BackgroundColor3 = Color3.new(0, 0, 0),
                BorderSizePixel = 0, Parent = sv,
            }, { corner(8), new("UIGradient", { Rotation = 90, Transparency = NumberSequence.new(1, 0) }) })
            local svKnob = new("Frame", {
                Size = UDim2.fromOffset(12, 12), AnchorPoint = Vector2.new(0.5, 0.5),
                BackgroundColor3 = Color3.new(1, 1, 1), BorderSizePixel = 0, Parent = sv,
            }, { circle(), stroke(Color3.new(0, 0, 0), 1.5, 0.2) })

            local hue = new("Frame", {
                Position = UDim2.fromOffset(14, 164), Size = UDim2.fromOffset(190, 12),
                BackgroundColor3 = Color3.new(1, 1, 1), BorderSizePixel = 0, Parent = f,
            }, {
                circle(),
                new("UIGradient", {
                    Color = ColorSequence.new({
                        ColorSequenceKeypoint.new(0, Color3.fromHSV(0, 1, 1)),
                        ColorSequenceKeypoint.new(1 / 6, Color3.fromHSV(1 / 6, 1, 1)),
                        ColorSequenceKeypoint.new(2 / 6, Color3.fromHSV(2 / 6, 1, 1)),
                        ColorSequenceKeypoint.new(3 / 6, Color3.fromHSV(3 / 6, 1, 1)),
                        ColorSequenceKeypoint.new(4 / 6, Color3.fromHSV(4 / 6, 1, 1)),
                        ColorSequenceKeypoint.new(5 / 6, Color3.fromHSV(5 / 6, 1, 1)),
                        ColorSequenceKeypoint.new(1, Color3.fromHSV(1, 1, 1)),
                    }),
                }),
            })
            local hueKnob = new("Frame", {
                Size = UDim2.fromOffset(6, 18), AnchorPoint = Vector2.new(0.5, 0.5),
                BackgroundColor3 = Color3.new(1, 1, 1), BorderSizePixel = 0, Parent = hue,
            }, { circle(), stroke(Color3.new(0, 0, 0), 1.5, 0.2) })

            label({
                Text = "HEX", TextColor3 = Theme.Sub, TextSize = 11, Font = Enum.Font.GothamBold,
                Position = UDim2.fromOffset(222, 52), Size = UDim2.fromOffset(60, 14), Parent = f,
            })
            local hexBox = new("TextBox", {
                Position = UDim2.fromOffset(222, 70), Size = UDim2.fromOffset(96, 26),
                BackgroundColor3 = Theme.Hover, BackgroundTransparency = 0.2, BorderSizePixel = 0,
                Text = "", TextColor3 = Theme.Text, Font = Enum.Font.Gotham, TextSize = 12,
                ClearTextOnFocus = false, Parent = f,
            }, { corner(8) })

            local function apply(fire)
                local c = Color3.fromHSV(h, s, v)
                tw(swatch, { BackgroundColor3 = c }, 0.2)
                sv.BackgroundColor3 = Color3.fromHSV(h, 1, 1)
                svKnob.Position = UDim2.fromScale(s, 1 - v)
                hueKnob.Position = UDim2.fromScale(h, 0.5)
                hexBox.Text = string.format("#%02X%02X%02X",
                    math.floor(c.R * 255 + 0.5), math.floor(c.G * 255 + 0.5), math.floor(c.B * 255 + 0.5))
                obj.Color = c
                if fire then
                    safe(o2.Callback, c)
                    saveConfig()
                end
            end
            apply(false)
            swatch.BackgroundColor3 = color

            local dragSV, dragHue = false, false
            local function svFrom(pos)
                s = math.clamp((pos.X - sv.AbsolutePosition.X) / math.max(sv.AbsoluteSize.X, 1), 0, 1)
                v = 1 - math.clamp((pos.Y - sv.AbsolutePosition.Y) / math.max(sv.AbsoluteSize.Y, 1), 0, 1)
                apply(true)
            end
            local function hueFrom(pos)
                h = math.clamp((pos.X - hue.AbsolutePosition.X) / math.max(hue.AbsoluteSize.X, 1), 0, 1)
                apply(true)
            end
            sv.InputBegan:Connect(function(i)
                if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then
                    dragSV = true
                    svFrom(i.Position)
                end
            end)
            hue.InputBegan:Connect(function(i)
                if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then
                    dragHue = true
                    hueFrom(i.Position)
                end
            end)
            connect(UIS.InputChanged, function(i)
                if i.UserInputType == Enum.UserInputType.MouseMovement or i.UserInputType == Enum.UserInputType.Touch then
                    if dragSV then svFrom(i.Position) end
                    if dragHue then hueFrom(i.Position) end
                end
            end)
            connect(UIS.InputEnded, function(i)
                if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then
                    dragSV, dragHue = false, false
                end
            end)
            hexBox.FocusLost:Connect(function()
                local r, g, b = hexBox.Text:match("^#?(%x%x)(%x%x)(%x%x)$")
                if r then
                    h, s, v = Color3.fromRGB(tonumber(r, 16), tonumber(g, 16), tonumber(b, 16)):ToHSV()
                    apply(true)
                else
                    apply(false)
                end
            end)

            head.MouseButton1Click:Connect(function()
                open = not open
                tw(f, { Size = UDim2.new(1, 0, 0, open and 190 or 40) }, 0.5)
            end)
            hoverable(f, head)

            function obj:Set(c, silent)
                h, s, v = c:ToHSV()
                apply(not silent)
            end
            function obj:Get() return obj.Color end
            register(o2, obj)
            return obj
        end

        -- profile card: picture (rbxthumb / asset url) or icon + title + two small lines
        function Tab:CreateProfile(o2)
            local f = box(76)
            local frameImg = new("Frame", {
                Size = UDim2.fromOffset(52, 52), Position = UDim2.fromOffset(12, 12),
                BackgroundColor3 = Theme.Hover, BorderSizePixel = 0, ClipsDescendants = true, Parent = f,
            }, { corner(o2.Circle and 26 or 12), stroke(Theme.Stroke, 1, 0.3) })
            local imgLabel
            local function setImage(img)
                if not imgLabel then
                    imgLabel = new("ImageLabel", {
                        Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1,
                        ScaleType = Enum.ScaleType.Crop, Parent = frameImg,
                    })
                end
                imgLabel.Image = tostring(img)
            end
            if o2.Image then
                setImage(o2.Image)
            elseif o2.Icon then
                local ih = new("Frame", { Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, Parent = frameImg })
                local ic = makeIcon(ih, o2.Icon, 24, Theme.Accent)
                onAccent(function() setIconColor(ic, Theme.Accent) end)
            end
            local t = label({
                Text = o2.Title or "", Font = Enum.Font.GothamBold, TextSize = 14,
                TextTruncate = Enum.TextTruncate.AtEnd,
                Position = UDim2.fromOffset(76, 10), Size = UDim2.new(1, -90, 0, 18), Parent = f,
            })
            local s = label({
                Text = o2.Subtitle or "", Font = Enum.Font.Gotham, TextColor3 = Theme.Sub, TextSize = 12,
                TextTruncate = Enum.TextTruncate.AtEnd,
                Position = UDim2.fromOffset(76, 30), Size = UDim2.new(1, -90, 0, 16), Parent = f,
            })
            local l3 = label({
                Text = o2.Line or "", Font = Enum.Font.Gotham, TextColor3 = Theme.Sub, TextSize = 11,
                TextTruncate = Enum.TextTruncate.AtEnd,
                Position = UDim2.fromOffset(76, 48), Size = UDim2.new(1, -90, 0, 16), Parent = f,
            })
            return {
                Set = function(_, n)
                    if n.Title then t.Text = n.Title end
                    if n.Subtitle then s.Text = n.Subtitle end
                    if n.Line then l3.Text = n.Line end
                    if n.Image then setImage(n.Image) end
                end,
            }
        end

        -- Add* aliases (the library's original names)
        Tab.AddProfile = Tab.CreateProfile
        Tab.AddSection = Tab.CreateSection
        Tab.AddLabel = Tab.CreateLabel
        Tab.AddParagraph = Tab.CreateParagraph
        Tab.AddButton = Tab.CreateButton
        Tab.AddToggle = Tab.CreateToggle
        Tab.AddSlider = Tab.CreateSlider
        Tab.AddDropdown = Tab.CreateDropdown
        Tab.AddInput = Tab.CreateInput
        Tab.AddKeybind = Tab.CreateKeybind
        Tab.AddColorPicker = Tab.CreateColorPicker

        if #tabs == 1 then selectTab(tab, true) end
        if expandTabs then layoutTabs(true) end
        return Tab
    end

    --// Info bar (top center): avatar, nick, script, injector, FPS, ping, server ----
    -- Click it to hide / show the window.
    local showPill = function() end
    if opts.InfoBar ~= false and opts.FPS ~= false then
        local lp = Players.LocalPlayer
        local Stats = game:GetService("Stats")
        local executorName = "Unknown"
        pcall(function()
            if identifyexecutor then executorName = tostring((identifyexecutor())) end
        end)
        local scriptName = opts.ScriptName or opts.Subtitle or titleText
        local nick = lp.Name
        local H = 40

        pill = new("CanvasGroup", {
            Size = UDim2.fromOffset(100, H), AnchorPoint = Vector2.new(0.5, 0),
            Position = UDim2.new(0.5, 0, 0, 4), BackgroundColor3 = Theme.Bg,
            BackgroundTransparency = 0.1, BorderSizePixel = 0, GroupTransparency = 1,
            Visible = false, Parent = gui,
        }, { circle(), new("UIScale", { Scale = 0.92 }) })
        local pillScale = pill:FindFirstChildOfClass("UIScale")
        new("Frame", { -- inset border
            Size = UDim2.new(1, -2, 1, -2), Position = UDim2.fromOffset(1, 1),
            BackgroundTransparency = 1, BorderSizePixel = 0, Parent = pill,
        }, { circle(), stroke(Theme.Stroke, 1, 0.2) })

        local x = 10
        local function separator()
            new("Frame", {
                Size = UDim2.fromOffset(1, 18), Position = UDim2.fromOffset(x + 7, (H - 18) / 2),
                BackgroundColor3 = Theme.Stroke, BorderSizePixel = 0, Parent = pill,
            })
            x += 15
        end
        local function block(caption, value, width)
            width = math.max(width or 0, textWidth(value, 12, Enum.Font.GothamBold), textWidth(caption, 9, Enum.Font.GothamBold)) + 2
            label({
                Text = caption, Font = Enum.Font.GothamBold, TextSize = 9, TextColor3 = Theme.Sub,
                Position = UDim2.fromOffset(x, 5), Size = UDim2.fromOffset(width, 12), Parent = pill,
            })
            local v = label({
                Text = value, Font = Enum.Font.GothamBold, TextSize = 12,
                Position = UDim2.fromOffset(x, 18), Size = UDim2.fromOffset(width, 16), Parent = pill,
            })
            x += width
            return v
        end

        -- avatar (headshot loads in the background and fades in)
        local avatar = new("ImageLabel", {
            Size = UDim2.fromOffset(26, 26), Position = UDim2.fromOffset(x, (H - 26) / 2),
            BackgroundColor3 = Theme.Hover, BorderSizePixel = 0, ImageTransparency = 1, Parent = pill,
        }, { circle() })
        x += 26 + 9
        task.spawn(function()
            local ok, img = pcall(function()
                return Players:GetUserThumbnailAsync(lp.UserId, Enum.ThumbnailType.HeadShot, Enum.ThumbnailSize.Size48x48)
            end)
            if ok and img and avatar.Parent then
                avatar.Image = img
                tw(avatar, { ImageTransparency = 0 }, 0.8, ES.Sine)
            end
        end)

        block("PLAYER", nick, 0)
        separator()
        block("SCRIPT", scriptName, 0)
        separator()
        block("INJECTOR", executorName, 0)
        separator()
        local fpsV = block("FPS", "--", 30)
        separator()
        local pingV = block("PING", "-- ms", 48)
        separator()
        local srvV = block("SERVER", "--/--", 34)
        pill.Size = UDim2.fromOffset(x + 12, H)

        local hitP = new("TextButton", {
            Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, Text = "",
            AutoButtonColor = false, ZIndex = 20, Parent = pill,
        })
        hitP.MouseEnter:Connect(function() tw(pill, { BackgroundTransparency = 0.3 }, 0.4) end)
        hitP.MouseLeave:Connect(function() tw(pill, { BackgroundTransparency = 0.1 }, 0.4) end)
        hitP.MouseButton1Click:Connect(function() setVisible(not visible) end)

        -- live values: numbers glide towards the real value instead of jumping
        local function readPing()
            local ok, v = pcall(function() return Stats.Network.ServerStatsItem["Data Ping"]:GetValue() end)
            if not (ok and type(v) == "number") then
                ok, v = pcall(function() return lp:GetNetworkPing() * 1000 end)
            end
            if ok and type(v) == "number" then return v end
            return nil
        end
        local function readServer()
            srvV.Text = #Players:GetPlayers() .. "/" .. Players.MaxPlayers
        end
        local fpsTarget, fpsShown = 60, 0
        local pingTarget, pingShown = readPing() or 0, 0
        readServer()
        local frames, acc, slow = 0, 0, 0
        connect(RunService.RenderStepped, function(dt)
            frames += 1
            acc += dt
            slow += dt
            if acc >= 0.4 then
                fpsTarget = frames / acc
                frames, acc = 0, 0
            end
            if slow >= 1 then
                slow = 0
                pingTarget = readPing() or pingTarget
                readServer()
            end
            if pill.Visible then
                local k = math.min(dt * 7, 1)
                fpsShown += (fpsTarget - fpsShown) * k
                pingShown += (pingTarget - pingShown) * k
                fpsV.Text = tostring(math.floor(fpsShown + 0.5))
                pingV.Text = math.floor(pingShown + 0.5) .. " ms"
            end
        end)

        showPill = function()
            pill.Visible = true
            pill.Position = UDim2.new(0.5, 0, 0, -4)
            tw(pill, { GroupTransparency = 0, Position = UDim2.new(0.5, 0, 0, 12) }, 1.2, ES.Quint)
            tw(pillScale, { Scale = 1 }, 1.2, ES.Quint)
        end
    end

    --// Intro: letters rise in one by one, then the window pops in ---------------
    local function afterReady()
        ready = true
        showPill()
        if cfgEnabled then
            task.delay(0.4, function() Lumen:LoadConfiguration() end)
        end
    end

    if useIntro then
        task.spawn(function()
            local fs = 40
            local text = opts.IntroText or opts.LoadingTitle or titleText

            local shade = new("Frame", {
                Size = UDim2.fromScale(1, 1), BackgroundColor3 = Color3.new(0, 0, 0),
                BackgroundTransparency = 1, BorderSizePixel = 0, Parent = gui,
            })
            local holderI = new("Frame", {
                AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5),
                Size = UDim2.fromOffset(10, 56), BackgroundTransparency = 1, Parent = gui,
            })

            local cells, x, bold = {}, 0, true
            for _, cp in utf8.codes(text) do
                local ch = utf8.char(cp)
                if ch == " " then
                    bold = false
                    x += 14
                else
                    local font = bold and Enum.Font.GothamBold or Enum.Font.Gotham
                    local w = TextService:GetTextSize(ch, fs, font, Vector2.new(1000, 1000)).X
                    local l = label({
                        Text = ch, Font = font, TextSize = fs, TextTransparency = 1,
                        TextColor3 = bold and Color3.new(1, 1, 1) or Color3.fromRGB(190, 190, 190),
                        TextXAlignment = Enum.TextXAlignment.Center,
                        Position = UDim2.fromOffset(x, 16), Size = UDim2.fromOffset(w + 2, 56),
                        Parent = holderI,
                    })
                    cells[#cells + 1] = { label = l, x = x }
                    x += w
                end
            end
            holderI.Size = UDim2.fromOffset(x, 56)
            local underline = new("Frame", {
                AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.new(0.5, 0, 1, 8),
                Size = UDim2.fromOffset(0, 2), BackgroundColor3 = Theme.Accent,
                BorderSizePixel = 0, Parent = holderI,
            }, { circle() })

            -- 1) background dims, letters rise in one by one
            tw(shade, { BackgroundTransparency = 0.5 }, 0.9, ES.Sine)
            task.wait(0.3)
            for i, c in ipairs(cells) do
                task.delay((i - 1) * 0.07, function()
                    tw(c.label, { TextTransparency = 0, Position = UDim2.fromOffset(c.x, 0) }, 0.7, ES.Quint)
                end)
            end
            task.wait(#cells * 0.07 + 0.4)
            if not gui.Parent then return end

            -- 2) underline draws out, short hold
            tw(underline, { Size = UDim2.fromOffset(x, 2) }, 0.7, ES.Quart)
            task.wait(1.0)
            if not gui.Parent then return end

            -- 3) letters float away
            tw(underline, { BackgroundTransparency = 1 }, 0.4, ES.Sine)
            for i, c in ipairs(cells) do
                task.delay((#cells - i) * 0.03, function()
                    tw(c.label, { TextTransparency = 1, Position = UDim2.fromOffset(c.x, -16) }, 0.5, ES.Quint)
                end)
            end
            task.wait(#cells * 0.03 + 0.5)
            if not gui.Parent then return end
            holderI:Destroy()

            -- 4) a line is drawn across the screen, the window unfolds from it
            tw(shade, { BackgroundTransparency = 1 }, 1.4, ES.Sine)
            visible = true
            unfold()
            shade:Destroy()
            if not gui.Parent then return end            afterReady()
        end)
    else
        setBlur(true, 0.4)
        afterReady()
    end

    return Window
end

return Lumen
